const raw = $json.body || $json;
const imageText = raw.reference_images || raw['Reference image URLs'] || raw.reference_image_urls || '';
const referenceImages = Array.isArray(imageText)
  ? imageText
  : String(imageText).split(/\r?\n|,/).map(v => v.trim()).filter(Boolean);
const product = {
  job_id: raw.job_id || `${raw.sku || raw.SKU}-${Date.now()}`,
  created_at: new Date().toISOString(),
  sku: raw.sku || raw.SKU,
  brand: raw.brand || raw.Brand,
  product_name: raw.product_name || raw['Product name'],
  included_items: raw.included_items || raw['Included items'],
  material: raw.material || raw.Material || '',
  size: raw.size || raw.Size || '',
  target_keyword: raw.target_keyword || raw['Target keyword'],
  target_buyer: raw.target_buyer || raw['Target buyer'] || '',
  reference_images: referenceImages
};
if (!product.sku || !product.brand || !product.product_name || !product.included_items || !product.target_keyword) {
  throw new Error('Missing required fields: sku, brand, product_name, included_items, target_keyword');
}
return [{ json: product }];

const input = $('Normalize Product Input').first().json;
const folder = $json;
return [{ json: { ...input, drive_folder_id: folder.id, drive_folder_url: folder.webViewLink || folder.webUrl || '' } }];

