const product = $('Extract Reference Analysis').first().json;
const response = $json;
const outputText = response.output_text || response.output?.flatMap(o => o.content || []).map(c => c.text).filter(Boolean).join('\n') || '{}';
let plan;
try { plan = JSON.parse(outputText.replace(/^```json\s*|```$/g, '').trim()); } catch (error) { plan = { raw: outputText, secondary_image_prompts: [], a_plus_content_prompts: [], compliance_checklist: [] }; }
const slots = [
  { slot: '01-main-image', file_name: '01-main-image.png', slot_name: 'Main Image', prompt: plan.main_image_prompt || '' },
  ...(plan.secondary_image_prompts || []).map(p => ({ slot: p.slot, file_name: `${p.slot}.png`, slot_name: p.title || p.slot, prompt: p.prompt || '', image_text_copy: p.image_text_copy || [] }))
];
const items = [];
for (const slot of slots) {
  for (const version of ['A', 'B']) {
    items.push({ json: { ...product, prompt_plan: plan, slot: slot.slot, slot_name: slot.slot_name, final_file_name: slot.file_name, version, image_prompt: slot.prompt, image_text_copy: slot.image_text_copy || [] } });
  }
}
return items;

const slot = $('Build 7 Slots x A/B Versions').item.json;
const imageUrl = $json.image_url || $json.url || $json.data?.[0]?.url || $json.output?.[0] || '';
if (!imageUrl) throw new Error('Image API response must include image_url, url, data[0].url, or output[0]');
return [{ json: { ...slot, generated_image_url: imageUrl, generation_response: $json } }];

