const meta = $('Attach Drive File Metadata').item.json;
const text = $json.output_text || $json.output?.flatMap(o => o.content || []).map(c => c.text).filter(Boolean).join('\n') || JSON.stringify($json);
let qa;
try { qa = JSON.parse(text.replace(/^```json\s*|```$/g, '').trim()); } catch (error) { qa = { status: 'needs_manual_review', summary: text }; }
return [{ json: { ...meta, qa, qa_status: qa.status || 'needs_manual_review', qa_findings: qa.summary || JSON.stringify(qa) } }];

